package com.nexodb.db;

import com.nexodb.model.DatabaseType;
import java.sql.*;
import java.util.*;

public final class DataQualityServiceTest {
    public static void main(String[] args)throws Exception{
        Class.forName("org.h2.Driver");try(Connection connection=DriverManager.getConnection("jdbc:h2:mem:quality;DB_CLOSE_DELAY=-1")){
            try(Statement statement=connection.createStatement()){
                statement.execute("CREATE TABLE customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(120), phone VARCHAR(30), note VARCHAR(100), status INT DEFAULT 1)");
                statement.execute("INSERT INTO customers(name,email,phone,note) VALUES ('Ana','ana@example.com','0991112222',''),('Luis',NULL,'0983334444','activo')");
            }
            var table=DataQualityService.describe(connection,DatabaseType.H2,"PUBLIC","CUSTOMERS");equal(List.of("ID"),table.primaryKeys());require(table.column("ID").autoIncrement(),"Identity column not detected");
            var profile=DataQualityService.profile(connection,table,()->false);equal(2L,profile.rows());var email=profile.columns().stream().filter(item->item.name().equals("EMAIL")).findFirst().orElseThrow();equal(1L,email.nulls());var note=profile.columns().stream().filter(item->item.name().equals("NOTE")).findFirst().orElseThrow();equal(1L,note.empty());
            var cancelled=new DataQualityService.Control();cancelled.cancel();boolean cancellationObserved=false;try{DataQualityService.profile(connection,table,cancelled);}catch(java.util.concurrent.CancellationException expected){cancellationObserved=true;}require(cancellationObserved,"Cancellation did not stop profiling");
            var preview=DataQualityService.previewMask(connection,table,List.of(new DataQualityService.MaskSelection("EMAIL",DataQualityService.MaskRule.EMAIL,""),new DataQualityService.MaskSelection("PHONE",DataQualityService.MaskRule.TELEFONO,"")),10,()->false);equal(2,preview.masked().size());require(String.valueOf(preview.masked().get(0).get(0)).endsWith("@ejemplo.invalid"),"Email was not masked");equal(2,DataQualityService.applyMask(connection,preview,()->false));
            try(Statement statement=connection.createStatement();ResultSet rows=statement.executeQuery("SELECT email, phone FROM customers ORDER BY id")){require(rows.next(),"Missing masked row");require(rows.getString(1).endsWith("@ejemplo.invalid"),"Masked email was not saved");require(rows.getString(2).matches("09[0-9]{8}"),"Masked phone was not saved");}
            var generated=DataQualityService.generate(table,3);require(!generated.columns().contains("ID"),"Identity column included in generator");connection.setAutoCommit(false);boolean transactionRejected=false;try{DataQualityService.insertGenerated(connection,generated,()->false);}catch(SQLException expected){transactionRejected=true;}finally{connection.rollback();connection.setAutoCommit(true);}require(transactionRejected,"An existing user transaction was committed by the generator");equal(3,DataQualityService.insertGenerated(connection,generated,()->false));try(Statement statement=connection.createStatement();ResultSet rows=statement.executeQuery("SELECT COUNT(*), COUNT(DISTINCT id) FROM customers")){rows.next();equal(5L,rows.getLong(1));equal(5L,rows.getLong(2));}
            boolean rejected=false;try{var noKey=new DataQualityService.Table(null,"PUBLIC","NO_KEY",List.of(new DataQualityService.Column("VALUE",Types.VARCHAR,"VARCHAR",30,true,false,false,false,null)),List.of(),"\"","\"PUBLIC\".\"NO_KEY\"");DataQualityService.previewMask(connection,noKey,List.of(new DataQualityService.MaskSelection("VALUE",DataQualityService.MaskRule.HASH,"")),5,()->false);}catch(SQLException expected){rejected=true;}require(rejected,"Masking without a primary key was accepted");
        }
        System.out.println("DataQualityServiceTest: OK (profile, deterministic preview, transactional masking, safe generated inserts and PK guard)");
    }
    private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    private static void equal(Object expected,Object actual){if(!Objects.equals(expected,actual))throw new AssertionError("Expected ["+expected+"] got ["+actual+"]");}
}
